// The mechanism tree's pure parts (docs/plans/mechanism-tree.md piece T1): the forward subgraph, the loop boxes and
// Tarjan's components, the generations by longest path once the feedback edges are set aside, and stable ordering, on
// a small fixture and on the registry the page draws (registry-data.ts, generated by scripts/couplings.ts).
import { describe, expect, it } from 'vitest';
import { components, drawClass, forward, mechanismTree, type LoopDecl, type TreeData, type TreeRow } from './graph.ts';
import { generations, layout } from './layout.ts';
import { REGISTRY } from './registry-data.ts';
import { treeSvg } from './svg.ts';

const row = (id: string, from: string[], to: string, extra: Partial<TreeRow> = {}): TreeRow =>
  ({ id, module: 'm', from, to, sign: '+', form: 'factor', cls: 'UNTAGGED', consts: [], note: id, ...extra });
// T → a → [s1 → s2] (a reflex) → b → a (feedback through the plant); a → c (fitted); d is never reached
const FIX: TreeData = {
  triggers: [{ path: 'trigger.t', label: 'T' }],
  nodes: [{ path: 'trigger.t', kind: 'trigger', label: 'T' }, { path: 'x.absent', kind: 'effector', label: 'Missing', absent: 'research/44 L2-01' }],
  rows: [
    row('r1', ['trigger.t'], 'a'),
    row('r2', ['a'], 'rx.s1'),
    row('r3', ['rx.s1'], 'rx.s2'),
    row('r4', ['rx.s2'], 'b', { cls: 'FIT', consts: [{ name: 'G', value: '1', source: '[FIT: x]' }] }),
    row('r5', ['b'], 'a'),
    row('r6', ['a'], 'c', { cls: 'SOURCED', consts: [{ name: 'K', value: '2', source: 'Guyton 1955' }] }),
    row('r7', ['a'], 'c', { cls: 'FIT', consts: [{ name: 'F', value: '3', source: '[FIT: y]' }] }),
    row('r8', ['b'], 'x.absent', { cls: 'ABSENT', absent: 'research/44 L2-01' }),
    row('r9', ['d'], 'a'),
  ],
};
const RX: LoopDecl[] = [{ id: 'loop.rx', label: 'Reflex', members: (p) => p.startsWith('rx.') }];

describe('forward(): the reachable subgraph', () => {
  it('reaches what the trigger reaches, breadth first, and only the edges from reached nodes', () => {
    const s = forward(FIX, 'trigger.t');
    expect(s.nodes).toEqual(['trigger.t', 'a', 'rx.s1', 'c', 'rx.s2', 'b', 'x.absent']);
    expect(s.edges.map((e) => e.row.id)).toEqual(['r1', 'r2', 'r3', 'r4', 'r5', 'r6', 'r7', 'r8']);
  });
});

describe('mechanismTree(): loop boxes, merged edges, classes, feedback', () => {
  const tree = mechanismTree(FIX, 'trigger.t', () => null, RX);
  it('collapses the declared reflex into one loop box holding its states; its inner rows are kept', () => {
    expect(tree.nodes.map((n) => `${n.id}:${n.kind}`)).toEqual(['trigger.t:trigger', 'a:state', 'loop.rx:loop', 'c:state', 'b:state', 'x.absent:effector']);
    expect(tree.nodes.find((n) => n.id === 'loop.rx')?.keys).toEqual(['rx.s1', 'rx.s2']);
    expect(tree.inner.get('loop.rx')?.map((r) => r.id)).toEqual(['r3']);
  });
  it('merges rows between the same two nodes and draws the most cautious class; a pass-through is NONE', () => {
    const ac = tree.edges.find((e) => e.from === 'a' && e.to === 'c');
    expect(ac?.rows.map((r) => r.id)).toEqual(['r6', 'r7']);
    expect(ac?.cls).toBe('FIT');
    expect(tree.edges.find((e) => e.to === 'loop.rx')?.cls).toBe('NONE');
    expect(drawClass(row('u', [], 'x', { consts: [{ name: 'Q', source: '—' }] }))).toBe('UNTAGGED');
  });
  it('an ABSENT edge keeps its audit id; the absent node its own', () => {
    const e = tree.edges.find((x) => x.to === 'x.absent');
    expect(e).toMatchObject({ cls: 'ABSENT', absent: 'research/44 L2-01' });
    expect(tree.nodes.find((n) => n.id === 'x.absent')?.absent).toBe('research/44 L2-01');
  });
  it('Tarjan: the loop a → reflex → b → a is one component; b → a is the feedback edge', () => {
    expect(tree.loops).toEqual([expect.arrayContaining(['a', 'loop.rx', 'b'])]);
    expect(tree.loops[0]).toHaveLength(3);
    expect(tree.edges.filter((e) => e.feedback).map((e) => `${e.from}>${e.to}`)).toEqual(['b>a']);
  });
  it('generations by longest path once the feedback edges are set aside', () => {
    expect(Object.fromEntries(generations(tree))).toEqual({ 'trigger.t': 0, a: 1, 'loop.rx': 2, c: 2, b: 3, 'x.absent': 4 });
  });
  it('components() on a plain cycle: one component, one feedback edge', () => {
    const r = components(['x', 'y', 'z'], [{ from: 'x', to: 'y' }, { from: 'y', to: 'z' }, { from: 'z', to: 'x' }], 'x');
    expect(r.sccs).toHaveLength(1);
    expect([...r.feedback]).toEqual([2]);
  });
});

/** Pinned per trigger (the picture the registry of R1 draws; a row added or reclassed moves these, deliberately). */
const PINS = {
  'trigger.bleed': { nodes: 77, edges: 127, feedback: 4, absent: 17, columns: 20, loop: 53 },
  'trigger.drug.propofol': { nodes: 72, edges: 121, feedback: 14, absent: 17, columns: 23, loop: 53 },
  'trigger.drug.phenylephrine': { nodes: 73, edges: 125, feedback: 22, absent: 17, columns: 21, loop: 53 },
  'trigger.drug.esmolol': { nodes: 74, edges: 125, feedback: 13, absent: 17, columns: 20, loop: 53 },
  'trigger.lungCondition.ptxTension': { nodes: 91, edges: 150, feedback: 4, absent: 19, columns: 23, loop: 55 },
  'trigger.ventilation.peep': { nodes: 91, edges: 150, feedback: 27, absent: 19, columns: 32, loop: 55 },
} as const;

describe('the registry the page draws', () => {
  for (const [trigger, pin] of Object.entries(PINS)) {
    it(`${trigger}: ${pin.nodes} nodes, ${pin.edges} edges, ${pin.feedback} feedback, ${pin.absent} absent, ${pin.columns} columns`, () => {
      const tree = mechanismTree(REGISTRY, trigger);
      const L = layout(tree);
      expect({
        nodes: tree.nodes.length, edges: tree.edges.length, feedback: tree.edges.filter((e) => e.feedback).length,
        absent: tree.edges.filter((e) => e.absent).length, columns: L.gens.length, loop: tree.loops[0]?.length,
      }).toEqual(pin);
      expect(L.gens[0]).toEqual([trigger]);
      // no edge drawn forward runs backward or within a column
      for (const e of tree.edges.filter((x) => !x.feedback)) expect(L.at.get(e.to)!.gen).toBeGreaterThan(L.at.get(e.from)!.gen);
    });
  }
  it('propofol: Ce, the drug factors, then SVR; the baroreflex is one loop box of its five states', () => {
    const tree = mechanismTree(REGISTRY, 'trigger.drug.propofol');
    const L = layout(tree);
    expect(L.gens[1]).toEqual(['pk.bus.cns.propCe']);
    expect(L.gens[2]).toEqual(['pk.fx.svr', 'pk.fx.ees', 'pk.fx.v0Frac', 'pk.fx.gv', 'pk.fx.gvHr', 'pk.fx.symp', 'pk.fx.setF', 'pk.bus.cns.hypPropEq', 'pk.bus.cns.hypVentPropEq']);
    expect(L.gens[3]).toEqual(['hemo.circ.p.rSys', 'neuro.resp.hypnoticDep']);
    const baro = tree.nodes.filter((n) => n.kind === 'loop' && n.label === 'Baroreflex');
    expect(baro.map((n) => n.keys)).toEqual([['circ.baro.gains', 'hemo.circ.baro.mapLp', 'hemo.circ.baro.set', 'hemo.circ.baro.es', 'hemo.circ.baro.ev']]);
    for (const k of ['hemo.circ.p.v0Sv', 'mon.abpMean', 'hemo.circ.mapNow']) expect(tree.nodes.some((n) => n.id === k), k).toBe(true);
  });
  it('is stable: the same registry and trigger draw the same string', () => {
    const a = treeSvg(mechanismTree(REGISTRY, 'trigger.ventilation.peep')).svg;
    expect(treeSvg(mechanismTree(REGISTRY, 'trigger.ventilation.peep')).svg).toBe(a);
  });
});
